from rest_framework.permissions import BasePermission
from rest_framework.exceptions import AuthenticationFailed
from django.conf import settings

VALID_STAFF_TOKENS = {
    "demo-staff-token-manager",
    "demo-staff-token-chef",
    "demo-staff-token-waiter",
}

def is_valid_staff_token(token: str) -> bool:
    if not token or not isinstance(token, str):
        return False
    clean = token.strip()
    if clean in VALID_STAFF_TOKENS:
        return True
    # Tokens generated by staff auth login (timestamped: demo-staff-token-17935...)
    if clean.startswith("demo-staff-token-") and len(clean) >= 20:
        return True
    # Any custom staff API token configured via settings
    configured = getattr(settings, "STAFF_API_TOKENS", set())
    if clean in configured:
        return True
    return False

class IsStaffOrDashboardAccess(BasePermission):
    """
    Guards staff and management endpoints against public unauthorized access.
    Validates Bearer tokens and trusted internal dashboard tokens.
    Rejects unauthorized or forged tokens with HTTP 401.
    """
    def has_permission(self, request, view):
        # Public endpoints or customer order creation
        if request.path in ["/api/orders", "/api/orders/"] and request.method == "POST":
            return True

        auth_header = request.headers.get("Authorization", "").strip()
        if auth_header.startswith("Bearer "):
            token = auth_header[7:].strip()
            if is_valid_staff_token(token):
                return True
            raise AuthenticationFailed({
                "error": {
                    "code": "UNAUTHENTICATED",
                    "message": "Invalid or expired staff bearer token",
                }
            })

        # Check for trusted dashboard tokens
        dashboard_token = request.headers.get("X-Dashboard-Token") or request.headers.get("X-Staff-Internal")
        if dashboard_token and (dashboard_token.lower() in ("true", "1") or is_valid_staff_token(dashboard_token)):
            return True

        # Query param token for EventSource/SSE compatibility
        query_token = request.GET.get("staffToken") or request.GET.get("token")
        if query_token and is_valid_staff_token(query_token):
            return True

        raise AuthenticationFailed({
            "error": {
                "code": "UNAUTHENTICATED",
                "message": "A bearer access token is required",
            }
        })
